IEnumerator ClickRoutine(UnityAction then)
{
    _busy = true;
    _over = false;
    var elapsed = 0f;
    var from = transform.localScale;
    while (elapsed < ClickDuration)
    {
        elapsed += Time.unscaledDeltaTime;
        var p = Mathf.Clamp01(elapsed / ClickDuration);
        var settle = Mathf.SmoothStep(0f, 1f, p);
        var dip = 1f - Mathf.Sin(p * Mathf.PI) * 0.06f;
        transform.localScale = Vector3.Lerp(from, _baseScale, settle) * dip;
        yield return null;
    }
    transform.localScale = _baseScale;
    transform.localRotation = Quaternion.identity;
    if (_column == null && _rt != null) _rt.anchoredPosition = _basePos;
    _hover = 0f;
    _busy = false;
    if (then != null) then();
}

input.new_string:
IEnumerator ClickRoutine(UnityAction then)
{
    _busy = true;
    var elapsed = 0f;
    var from = transform.localScale;
    var columnOwnsScale = _column != null;
    while (elapsed < ClickDuration)
    {
        elapsed += Time.unscaledDeltaTime;
        ClickPulse = Punch(Mathf.Clamp01(elapsed / ClickDuration));
        if (!columnOwnsScale)
            transform.localScale = from * Mathf.Lerp(1f, SoloClickPop, ClickPulse);
        yield return null;
    }
    ClickPulse = 0f;
    if (!columnOwnsScale)
        transform.localScale = from;
    _busy = false;
    if (then != null) then();
}

static float Punch(float p)
{
    const float peakAt = 0.32f;
    if (p <= peakAt)
    {
        var t = p / peakAt;
        return 1f - (1f - t) * (1f - t);
    }
    return 1f - Mathf.SmoothStep(0f, 1f, (p - peakAt) / (1f - peakAt));
}

